impl AggregationContainer {
    /// Creates a builder for [`AggregationContainer`].
    pub fn builder() -> AggregationContainerBuilder {
        AggregationContainerBuilder::new()
    }
}

/// Builder for [`AggregationContainer`].
#[must_use = "the builder does nothing until `build()` is called"]
pub struct AggregationContainerBuilder<S = (crate::typed::builder::NotSet,)> {
    variant: Option<AggregationContainerKind>,
    aggregations: Option<indexmap::IndexMap<String, AggregationContainer>>,
    meta: Option<crate::typed::_types::Metadata>,
    _state: std::marker::PhantomData<S>,
}

impl AggregationContainerBuilder<(crate::typed::builder::NotSet,)> {
    pub(crate) fn new() -> Self {
        AggregationContainerBuilder {
            variant: None,
            aggregations: None,
            meta: None,
            _state: std::marker::PhantomData,
        }
    }
}

impl<S0> AggregationContainerBuilder<(S0,)> {
    fn with_state<N>(self) -> AggregationContainerBuilder<N> {
        AggregationContainerBuilder {
            variant: self.variant,
            aggregations: self.aggregations,
            meta: self.meta,
            _state: std::marker::PhantomData,
        }
    }

    /// Sub-aggregations for this aggregation.
    /// Only applies to bucket aggregations.
    pub fn aggregations(
        mut self,
        value: impl Into<indexmap::IndexMap<String, AggregationContainer>>,
    ) -> Self {
        self.aggregations = Some(value.into());
        self
    }

    /// Sets [`aggregations`](Self::aggregations) if `value` is `Some`.
    pub fn maybe_aggregations(
        mut self,
        value: Option<indexmap::IndexMap<String, AggregationContainer>>,
    ) -> Self {
        self.aggregations = value;
        self
    }

    /// Adds an entry to [`aggregations`](Self::aggregations).
    pub fn add_aggregations(
        mut self,
        key: impl Into<String>,
        value: impl Into<AggregationContainer>,
    ) -> Self {
        self.aggregations
            .get_or_insert_with(Default::default)
            .insert(key.into(), value.into());
        self
    }

    /// Adds an entry to [`aggregations`](Self::aggregations), with a builder.
    pub fn add_aggregations_with(
        self,
        key: impl Into<String>,
        f: impl FnOnce(
            AggregationContainerBuilder,
        ) -> AggregationContainerBuilder<(crate::typed::builder::Set,)>,
    ) -> Self {
        self.add_aggregations(key, f(AggregationContainerBuilder::new()).build())
    }

    pub fn meta(mut self, value: impl Into<crate::typed::_types::Metadata>) -> Self {
        self.meta = Some(value.into());
        self
    }

    /// Sets [`meta`](Self::meta) if `value` is `Some`.
    pub fn maybe_meta(mut self, value: Option<crate::typed::_types::Metadata>) -> Self {
        self.meta = value;
        self
    }
}

